$(function () {
  $.insertHtmlTyo({
    jsonFiles: ['kessan'],
    dataFolder: 'json/', 
    targetClass: 'avanti',
    theme: 0,
    minmax: 1,
    mmFuel: 1,
    done: function () {
      // jsonデータの組み込みが成功した後の処理
      $.when(
        get_searchList()
      )
      .done(function () {
        // 全ての処理が正常に完了したとき
        $('#loader-bg').fadeOut(500); // ローディング画面を消す
      })
      .fail(function () {
        // get_searchList() の取得などに失敗したとき
        console.error('リストの取得に失敗しました。');
        $('#loader-bg').fadeOut(500); // フリーズを防ぐため、失敗時も必ずローディングを消す
        
        // （任意）リスト部分にエラーメッセージを出したい場合はここに追記
        // $('#search_list_area').html('<p>情報を取得できませんでした。</p>');
      });
    },
    // もし $.insertHtmlTyo 側のプラグインにエラー処理機能(fail)が備わっている場合のための記述
    fail: function () {
      console.error('大元のJSONファイルの読み込みに失敗しました。');
      $('#loader-bg').fadeOut(500);
    }
  });
});


